def move_documents_to_private_storage(apps, schema_editor):
    """Les justificatifs déjà envoyés quittent MEDIA_ROOT (servi publiquement) pour le stockage privé."""
    DriverDocument = apps.get_model("drivers", "DriverDocument")
    for name in DriverDocument.objects.exclude(file="").values_list("file", flat=True):
        source = Path(settings.MEDIA_ROOT) / name
        target = Path(settings.PRIVATE_MEDIA_ROOT) / name
        if source.exists() and not target.exists():
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.move(str(source), str(target))


